WITH q1 AS ( SELECT cliente, SUM(faturamento) AS faturamento FROM pedidos_efetivos WHERE strftime('%Y', emissao) = '2026' AND strftime('%m', emissao) BETWEEN '01' AND '03' GROUP BY cliente ), q2 AS ( SELECT cliente, SUM(faturamento) AS faturamento FROM pedidos_efetivos WHERE strftime('%Y', emissao) = '2026' AND strftime('%m', emissao) BETWEEN '04' AND '06' GROUP BY cliente ) SELECT q1.cliente, ROUND((q2.faturamento - q1.faturamento) / NULLIF(q1.faturamento, 0) * 100, 2) AS percent_change, CASE WHEN (q2.faturamento - q1.faturamento) / NULLIF(q1.faturamento, 0) > 0 THEN 'Cresceu' WHEN (q2.faturamento - q1.faturamento) / NULLIF(q1.faturamento, 0) < 0 THEN 'Caiu' ELSE 'Sem mudança' END AS status FROM q1 JOIN q2 ON q1.cliente = q2.cliente ORDER BY percent_change DESC;